/** Cleared: every test done, none reactive, the group confirmed (the database takes ABO and RhD from the results). Reactive: a screen was reactive. Rejected: not released for another reason, said in the note (a group that stays anomalous after repeats, PBTA Standards ch.4 G.2.7; information from the donor after donation). Reactive and Rejected discard every component still in quarantine. */
export interface DonationClearanceIn {
  outcome: "Cleared" | "Reactive" | "Rejected";
  note?: string | null;
}

/** The second person who checked the number and the label signs with their own credentials (the PBTA SOP on labelling): someone else holding blood_center.process (the verifiers and the Lab Admin hold it too). */
export interface ComponentReleaseIn {
  checker_username: string;
  checker_password: string;
}

