/** Donations and the worklists — GET /api/v1/blood-center/donations (who may call: holders of blood_center.view). */
export function listDonations(query?: { status?: "Accepted" | "Deferred" | "Collected" | "Unsuccessful" | "Cleared" | "Reactive" | "Rejected" | null; donor_id?: number | null; date_from?: string | null; date_to?: string | null; limit?: number; before_id?: number | null }): Promise<DonationOut[]> {
  return api<DonationOut[]>("GET", withQuery(`/blood-center/donations`, query), undefined);
}

/** One donation, from the donor to the patients — GET /api/v1/blood-center/donations/{donation_id} (who may call: holders of blood_center.view). */
export function getDonation(donation_id: number): Promise<DonationDetailOut> {
  return api<DonationDetailOut>("GET", `/blood-center/donations/${donation_id}`, undefined);
}

/** Clear a donation, or record it reactive — POST /api/v1/blood-center/donations/{donation_id}/clearance (who may call: holders of blood_center.release). */
export function clear(donation_id: number, body: DonationClearanceIn): Promise<DonationDetailOut> {
  return api<DonationDetailOut>("POST", `/blood-center/donations/${donation_id}/clearance`, body);
}

/** The quarantine and the components — GET /api/v1/blood-center/components (who may call: holders of blood_center.view). */
export function listComponents(query?: { status?: "Quarantine" | "Released" | "Discarded" | "Processed" | null; component?: "WholeBlood" | "RedCells" | "FreshFrozenPlasma" | "Cryoprecipitate" | "Platelets" | null; limit?: number; before_id?: number | null }): Promise<CenterComponentOut[]> {
  return api<CenterComponentOut[]>("GET", withQuery(`/blood-center/components`, query), undefined);
}

/** Release a component into the blood bank — POST /api/v1/blood-center/components/{component_id}/release (who may call: holders of blood_center.release). */
export function release(component_id: number, body: ComponentReleaseIn): Promise<CenterComponentOut> {
  return api<CenterComponentOut>("POST", `/blood-center/components/${component_id}/release`, body, { idempotent: true });
}

/** A component's label — GET /api/v1/blood-center/components/{component_id}/label (who may call: holders of blood_center.process or blood_center.release). */
export function componentLabel(component_id: number): Promise<PrintOut_BloodComponentLabelFieldsOut_> {
  return api<PrintOut_BloodComponentLabelFieldsOut_>("GET", `/blood-center/components/${component_id}/label`, undefined);
}

/** One unit and its whole chain — GET /api/v1/blood/units/{unit_id} (who may call: holders of blood.view). */
export function getUnit(unit_id: number): Promise<BloodUnitTraceOut> {
  return api<BloodUnitTraceOut>("GET", `/blood/units/${unit_id}`, undefined);
}
